svg.script:
const BASE = "https:/" + "/cdn.jsdelivr.net/gh/jaromaz/jslinux-mobile@master/";
const frame = document.getElementById("linux_frame");

console.log("[PASTE DEBUG] Outer SVG script started!");

const storageShim = `<base href="${BASE}" /><script>
  try { window.localStorage.getItem("t"); } catch (e) {
    const mem = {};
    Object.defineProperty(window, "localStorage", { value: {
      getItem: k => mem[k] || null,
      setItem: (k, v) => { mem[k] = String(v); },
      removeItem: k => { delete mem[k]; },
      clear: () => { for (const k in mem) delete mem[k]; }
    }});
  }
  try { document.cookie; } catch (e) {
    let c = "";
    Object.defineProperty(document, "cookie", { get: () => c, set: v => { c = v; } });
  }
<\/script>`;

fetch(BASE + "index.html")
  .then(res => {
    if (!res.ok) throw new Error("HTTP " + res.status);
    return res.text();
  })
  .then(html => {
    const injected = html.replace(/<head[^>]*>/i, match => match + storageShim);
    const win = frame.contentWindow;
    const doc = frame.contentDocument || win.document;
    doc.open();
    doc.write(injected);
    doc.close();

    // Attach Ctrl+V paste handler directly to the iframe's window & document
    async function onFrameKeyDown(e) {
      if ((e.ctrlKey || e.metaKey) && e.key && e.key.toLowerCase() === "v") {
        console.log("[PASTE DEBUG] Ctrl+V caught! pc =", typeof win.pc, "term =", typeof win.term);
        e.preventDefault();
        e.stopImmediatePropagation();

        let text = "";
        try {
          text = await navigator.clipboard.readText();
          console.log("[PASTE DEBUG] Clipboard API text:", JSON.stringify(text));
        } catch (err) {
          console.warn("[PASTE DEBUG] Clipboard API blocked:", err.message);
          text = win.prompt("Press Ctrl+V here and click OK to paste into Linux:") || "";
          console.log("[PASTE DEBUG] Prompt text:", JSON.stringify(text));
        }

        if (!text) return;

        const clean = text.split("\r\n").join("\n").split("\n").join("\r");
        let idx = 0;

        const typer = setInterval(() => {
          if (idx >= clean.length) {
            console.log("[PASTE DEBUG] Done typing", clean.length, "chars.");
            clearInterval(typer);
            return;
          }
          const code = clean.charCodeAt(idx++);
          if (win.pc && win.pc.serial && typeof win.pc.serial.send_char === "function") {
            win.pc.serial.send_char(code);
          } else if (win.term && typeof win.term.send_chars === "function") {
            win.term.send_chars(String.fromCharCode(code));
          } else {
            console.error("[PASTE DEBUG] No serial or term found! Keys on win:", Object.keys(win).filter(k => k.includes("pc") || k.includes("term") || k.includes("serial")));
            clearInterval(typer);
          }
        }, 40);
      }
    }

    win.addEventListener("keydown", onFrameKeyDown, true);
    doc.addEventListener("keydown", onFrameKeyDown, true);
    console.log("[PASTE DEBUG] Keydown listeners attached to iframe!");
  })
  .catch(err => {
    console.error("[PASTE DEBUG] Fetch error:", err);
  });
